import {GitHubFile,fingerprint,newSyncKey,validateConnection,syncDecision} from './sync-core.js';
import {escapeHTML as h,download,parseWorkspaceBackup} from './core.js';
export function createDeviceSync(ctx) {
 const storage='ascend.sync.connection.v1';let config=null,busy=false,pending=null,status='Not connected',lastSync='',verified=false,enabled=true;
 try{config=JSON.parse(localStorage.getItem(storage)||'null');if(config)validateConnection(config);}catch{config=null;status='Saved connection needs to be imported again.';}
 const persist=()=>localStorage.setItem(storage,JSON.stringify(config));
 function refresh(){for(const el of document.querySelectorAll('[data-sync-status]'))el.textContent=status;if(location.hash==='#sync'&&!document.querySelector('dialog[open]'))ctx.render();}
 async function sync(choice='') {
  if(busy||!config||!enabled||ctx.isLocked())return;
  busy=true;status='Checking encrypted cloud file…';refresh();
  try {
   const api=new GitHubFile(config);await api.verify();verified=true;
   const local=structuredClone(ctx.getState()),localHash=await fingerprint(local),remote=await api.read();
   if(!remote){const sha=await api.write(local);config.baseline=localHash;config.sha=sha;pending=null;}
   else {
    if(choice&&pending?.remote&&(pending.remote.sha!==remote.sha||pending.localHash!==localHash)){pending={remote,localHash};status='A copy changed after review. Review both versions again.';return;}
    const remoteHash=await fingerprint(remote.workspace),decision=choice||syncDecision(localHash,remoteHash,config.baseline);
    if(decision==='conflict'){pending={remote,localHash};status='Both devices have changes. Review the two versions below.';return;}
    if(decision==='pull'){
     // Recheck after network/decryption so edits made while checking cannot be lost.
     if(await fingerprint(ctx.getState())!==localHash){status='New local edits detected. Sync again.';return;}
     if(!ctx.applyRemote(remote.workspace))throw Error('The cloud workspace could not be saved locally. Your current copy is preserved.');
     config.baseline=remoteHash;config.sha=remote.sha;
    }else if(decision==='push'){config.sha=await api.write(local,remote.sha);config.baseline=localHash;}
    else {config.baseline=localHash;config.sha=remote.sha;}
    pending=null;
   }
   config.lastSync=new Date().toISOString();persist();lastSync=config.lastSync;status='Up to date';
  } catch(e){status=e.message||'Sync failed. Your local records are preserved.';if(e.status===409||e.status===422)pending={retry:true};}
  finally{busy=false;refresh();}
 }
 function page(){const counts=w=>`${w.applications.length} applications · ${w.tasks.length} tasks · ${(w.events||[]).length} events`;return ctx.header('Device sync','An encrypted workspace file in your own private GitHub repository.')+`<section class="panel"><h2 data-sync-status>${h(status)}</h2><p>${config?`Connected to ${h(config.owner)}/${h(config.repo)}`:'Connect once here, then import the same connection on your iPhone.'}</p>${config?.lastSync?`<p>Last synced ${h(new Date(config.lastSync).toLocaleString())}</p>`:''}<div class="button-group">${config?ctx.btn('Sync now','cloud-now','primary')+ctx.btn('Transfer connection to iPhone','cloud-export','secondary')+ctx.btn('Disconnect this browser','cloud-disconnect','ghost'):ctx.btn('Set up private sync','cloud-setup','primary')+ctx.btn('Import device connection','cloud-import','secondary')}</div><input type="file" id="sync-connection-file" accept=".json" hidden><p class="body-copy">While unlocked and open, Ascend checks roughly once a minute and syncs saved edits after 15 seconds. The iPhone app syncs while active; iOS does not guarantee closed-app background sync. Full workspace contents, including documents, are encrypted before upload. The repository and its commit history store ciphertext.</p><p class="body-copy">Your token and random key stay on this browser; the app keeps them in iOS Keychain. Connection files contain both secrets—transfer privately and remove extra copies. They are excluded from workspace backups. The website’s 2010 lock is a local privacy screen, not server authentication.</p></section>${pending?.remote?`<section class="panel sync-conflict"><h2>Choose which workspace to keep</h2><p>This device: ${counts(ctx.getState())}</p><p>Cloud: ${counts(pending.remote.workspace)}</p><p>Replacing either copy affects the complete workspace. Save both backups first if each has changes you need.</p><div class="button-group">${ctx.btn('Download this device backup','cloud-backup-local','secondary')}${ctx.btn('Download cloud backup','cloud-backup-remote','secondary')}</div><div class="button-group">${ctx.btn('Use cloud workspace on this device','cloud-use-remote','primary')}${ctx.btn('Replace cloud with this device','cloud-use-local','secondary')}</div></section>`:''}<section class="panel"><h2>One-time GitHub setup</h2><ol><li>Open <a href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener noreferrer">GitHub’s fine-grained token page</a>.</li><li>Select only <strong>ascend-private-sync</strong>, and give <strong>Contents: read and write</strong> permission. Choose an expiry you can renew.</li><li>Paste that token into Set up private sync. A random encryption key is generated for the first device.</li><li>Export the connection and import it in the app’s Device sync screen. Keep the key: a replacement key cannot decrypt existing cloud history.</li></ol><a href="https://github.com/YoussefElb-Dev/ascend-private-sync" target="_blank" rel="noopener noreferrer">Open private sync repository ↗</a></section>`;}
 function setup(){ctx.formDialog('Connect private sync',ctx.field('GitHub owner','owner','YoussefElb-Dev','text','required autocomplete="off"')+ctx.field('Private repository','repo','ascend-private-sync','text','required autocomplete="off"')+ctx.field('Fine-grained GitHub token','token','','password','required autocomplete="off"')+ctx.field('Existing sync key (leave blank on your first device)','key','','password','autocomplete="off"')+'<p class="full-width body-copy">If the cloud file already exists, import its original connection/key. Never create a new key to replace a key you still need.</p>',async v=>{if(busy)throw Error('Wait for the current sync to finish.');busy=true;try{const next={format:'ascend-sync-connection-v1',owner:v.owner.trim(),repo:v.repo.trim(),token:v.token.trim(),key:v.key.trim()||newSyncKey()};validateConnection(next);await new GitHubFile(next).verify();const old=config;config=next;try{persist();}catch(e){config=old;throw e;}verified=true;status='Connected. Choose Sync now to exchange workspaces.';ctx.render();}finally{busy=false;}},'Save connection');}
 async function handle(key){if(!key.startsWith('cloud-'))return false;if(busy){ctx.toast('Wait for the current sync to finish.');return true;}switch(key){case'cloud-setup':setup();break;case'cloud-now':await sync();break;case'cloud-disconnect':localStorage.removeItem(storage);config=null;verified=false;pending=null;status='Disconnected. Local records and the encrypted cloud file remain.';ctx.render();break;case'cloud-export':download('ascend-private-device-connection.json',JSON.stringify({...config,baseline:undefined,sha:undefined,lastSync:undefined},null,2),'application/json');break;case'cloud-import':document.querySelector('#sync-connection-file')?.click();break;case'cloud-backup-local':download('ascend-device-before-sync.json',JSON.stringify(ctx.getState(),null,2),'application/json');break;case'cloud-backup-remote':if(pending?.remote)download('ascend-cloud-before-sync.json',JSON.stringify(pending.remote.workspace,null,2),'application/json');break;case'cloud-use-remote':case'cloud-use-local':{const choice=key==='cloud-use-remote'?'pull':'push';ctx.formDialog('Confirm workspace replacement','<p>The complete '+(choice==='pull'?'workspace on this device':'encrypted cloud workspace')+' will be replaced. Download both backups first if needed.</p>',async()=>{await sync(choice);setTimeout(()=>ctx.render(),0);return !pending;},'Replace workspace');break;}default:return false;}return true;}
 document.addEventListener('change',async e=>{if(e.target.id!=='sync-connection-file'||!e.target.files[0])return;if(busy){ctx.toast('Wait for the current sync to finish.');return;}busy=true;try{const f=e.target.files[0];if(f.size>16000)throw Error('Choose a small Ascend connection file.');const next=JSON.parse(await f.text());if(next.format!=='ascend-sync-connection-v1')throw Error('This is not a device connection file.');validateConnection(next);await new GitHubFile(next).verify();config={format:next.format,owner:next.owner,repo:next.repo,token:next.token,key:next.key};persist();verified=true;pending=null;status='Connection imported. Choose Sync now.';ctx.render();}catch(e){ctx.toast(e.message);}finally{busy=false;}});
 let debounce;return {page,handle,sync,changed:()=>{clearTimeout(debounce);debounce=setTimeout(()=>{if(!pending)sync();},15000);},start:()=>{setInterval(()=>{if(!document.hidden&&!pending)sync();},60000);setTimeout(()=>sync(),1200);window.addEventListener('online',()=>sync());window.addEventListener('ascend:unlock',()=>sync());},setEnabled:v=>{enabled=v;}};
}
